import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type LockedScreenNotifsProps = Record<string, any>;

const MessagesIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ borderRadius: size * 0.22 }}>
    <rect width="100" height="100" fill="#34C759" />
    <path d="M 50 25 C 28 25 18 38 18 52 C 18 61 23 68 30 73 C 28 79 23 83 23 83 C 23 83 34 83 41 78 C 44 79 47 79 50 79 C 72 79 82 66 82 52 C 82 38 72 25 50 25 Z" fill="white" />
  </svg>
);

const MapsIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ borderRadius: size * 0.22, backgroundColor: 'white' }}>
    <path d="M50 22 C36 22 26 33 26 47 C26 68 50 82 50 82 C50 82 74 68 74 47 C74 33 64 22 50 22 Z M50 56 C45 56 41 52 41 47 C41 42 45 38 50 38 C55 38 59 42 59 47 C59 52 55 56 50 56 Z" fill="#EA4335" />
  </svg>
);

const LockedScreenNotifs: React.FC<LockedScreenNotifsProps> = ({
  backgroundColor = "#0C0F16",
  transparentBackground = false,
  durationInSeconds = 10,
  phoneScale = 0.9,
  
  n1_startFrame = 30,
  n1_posX = 50,
  n1_posY = 35,
  n1_width = 80,
  n1_height = 14,
  n1_title = "Prahlad",
  n1_titleSize = 36,
  n1_message = "Hey man could you give me a ride?",
  n1_messageSize = 32,
  n1_time = "now",
  n1_timeSize = 24,

  n2_startFrame = 120,
  n2_posX = 50,
  n2_posY = 55,
  n2_width = 80,
  n2_height = 14,
  n2_title = "Google Maps",
  n2_titleSize = 36,
  n2_message = "+90 minutes to destination",
  n2_messageSize = 32,
  n2_time = "now",
  n2_timeSize = 24,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Phone Dimensions
  const phoneW = 500 * s * phoneScale;
  const phoneH = 1000 * s * phoneScale;
  const phoneRadius = 60 * s * phoneScale;

  // Wake up logic: Screen turns on slightly before the first notification
  const firstNotifFrame = Math.min(n1_startFrame, n2_startFrame);
  const wakeFrame = Math.max(0, firstNotifFrame - 20);
  
  const screenBrightness = interpolate(
    frame,
    [wakeFrame, wakeFrame + 15],
    [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  const renderNotification = (
    startFrame: number, 
    x: number, 
    y: number, 
    w: number, 
    h: number, 
    title: string, 
    msg: string, 
    time: string, 
    titleSz: number, 
    msgSz: number, 
    timeSz: number, 
    IconComp: React.FC<{size: number}>
  ) => {
    const entranceProgress = spring({
      frame: Math.max(0, frame - startFrame),
      fps,
      config: { damping: 16, stiffness: 140 }
    });

    const notifOpacity = interpolate(
      frame,
      [startFrame, startFrame + 5],
      [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
    );

    const scale = interpolate(entranceProgress, [0, 1], [0.85, 1]);
    const yOffset = interpolate(entranceProgress, [0, 1], [30 * s, 0]);

    return (
      <div style={{
        position: 'absolute',
        left: `${x}%`,
        top: `${y}%`,
        width: `${w}%`,
        height: `${h}%`,
        transform: `translate(-50%, 0) scale(${scale}) translateY(${yOffset}px)`,
        opacity: notifOpacity,
        backgroundColor: 'rgba(28, 28, 30, 0.9)',
        borderRadius: 24 * s * phoneScale,
        padding: `${16 * s * phoneScale}px`,
        boxSizing: 'border-box',
        display: 'flex',
        flexDirection: 'row',
        gap: 12 * s * phoneScale,
        boxShadow: `0 ${10 * s}px ${30 * s}px rgba(0,0,0,0.3)`,
        transition: "none",
        overflow: 'hidden'
      }}>
        <div style={{ paddingTop: 2 * s }}>
          <IconComp size={36 * s * phoneScale} />
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', flex: 1, minWidth: 0 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 2 * s }}>
            <span style={{ color: 'white', fontWeight: 600, fontSize: titleSz * s * phoneScale, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {title}
            </span>
            <span style={{ color: '#8e8e93', fontSize: timeSz * s * phoneScale, marginLeft: 8 * s }}>
              {time}
            </span>
          </div>
          <span style={{ color: '#d1d1d6', fontSize: msgSz * s * phoneScale, lineHeight: 1.3, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
            {msg}
          </span>
        </div>
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, justifyContent: 'center', alignItems: 'center' }}>
      
      {/* Phone Hardware Container */}
      <div style={{
        position: 'relative',
        width: phoneW,
        height: phoneH,
        backgroundColor: 'black',
        borderRadius: phoneRadius,
        border: `${12 * s * phoneScale}px solid #1a1a1a`,
        boxShadow: `inset 0 0 0 ${2 * s}px #444, 0 0 ${80 * s}px rgba(0,0,0,0.5)`,
        overflow: 'hidden',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center'
      }}>
        
        {/* Dynamic Island */}
        <div style={{
          position: 'absolute',
          top: 14 * s * phoneScale,
          left: '50%',
          transform: 'translateX(-50%)',
          width: 130 * s * phoneScale,
          height: 38 * s * phoneScale,
          backgroundColor: '#000',
          borderRadius: 20 * s * phoneScale,
          zIndex: 20,
        }} />

        {/* Screen Background (turns on to a dark gradient wallpaper) */}
        <div style={{
          position: 'absolute',
          inset: 0,
          background: 'linear-gradient(180deg, #1c212b 0%, #0d1117 100%)',
          opacity: screenBrightness,
          zIndex: 1,
          transition: "none"
        }} />

        {/* Screen Content Wrapper */}
        <div style={{
          position: 'absolute',
          inset: 0,
          zIndex: 2,
          opacity: screenBrightness,
          transition: "none"
        }}>
          
          {/* Status Bar Simplified */}
          <div style={{
            position: 'absolute',
            top: 20 * s * phoneScale,
            right: 30 * s * phoneScale,
            display: 'flex',
            gap: 6 * s * phoneScale,
            alignItems: 'flex-end',
            opacity: 0.8
          }}>
             <div style={{ display: 'flex', alignItems: 'flex-end', gap: 2 * s * phoneScale, height: 12 * s * phoneScale, marginRight: 4 * s }}>
                <div style={{ width: 3 * s, height: 4 * s, backgroundColor: 'white', borderRadius: 1 }}/>
                <div style={{ width: 3 * s, height: 6 * s, backgroundColor: 'white', borderRadius: 1 }}/>
                <div style={{ width: 3 * s, height: 9 * s, backgroundColor: 'white', borderRadius: 1 }}/>
                <div style={{ width: 3 * s, height: 12 * s, backgroundColor: 'white', borderRadius: 1 }}/>
             </div>
             <div style={{ width: 22 * s * phoneScale, height: 12 * s * phoneScale, border: '1px solid white', borderRadius: 4 * s, padding: 1, position: 'relative' }}>
                <div style={{ width: '85%', height: '100%', backgroundColor: 'white', borderRadius: 2 * s }} />
                <div style={{ position: 'absolute', right: -3 * s, top: '25%', width: 2 * s, height: '50%', backgroundColor: 'white', borderRadius: '0 2px 2px 0' }} />
             </div>
          </div>

          {/* Lock Screen Clock */}
          <div style={{
            position: 'absolute',
            top: '15%',
            width: '100%',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            transition: "none",
            transform: `scale(${interpolate(screenBrightness, [0, 1], [0.95, 1])})`
          }}>
            <div style={{ fontSize: 96 * s * phoneScale, color: 'white', fontWeight: 300, letterSpacing: -2 * s, lineHeight: 1 }}>
              9:41
            </div>
            <div style={{ fontSize: 24 * s * phoneScale, color: '#e5e5e5', marginTop: 8 * s, fontWeight: 500, letterSpacing: 0.5 }}>
              Monday, June 10
            </div>
          </div>

          {/* Notifications */}
          {renderNotification(
            n1_startFrame, n1_posX, n1_posY, n1_width, n1_height, 
            n1_title, n1_message, n1_time, n1_titleSize, n1_messageSize, n1_timeSize, 
            MessagesIcon
          )}
          
          {renderNotification(
            n2_startFrame, n2_posX, n2_posY, n2_width, n2_height, 
            n2_title, n2_message, n2_time, n2_titleSize, n2_messageSize, n2_timeSize, 
            MapsIcon
          )}

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LockedScreenNotifs;